function readBody(req: IncomingMessage): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => chunks.push(c));
    req.on("end", () => resolve(Buffer.concat(chunks)));
    req.on("error", reject);
  });
}

beforeAll(async () => {
  server = createServer(async (req, res) => {
    received.push({ url: req.url ?? "", contentType: req.headers["content-type"], body: await readBody(req) });
    res.writeHead(upstreamStatus, { "content-type": "application/json", "retry-after": "7" });
    res.end('{"id":"stub"}');
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  port = (server.address() as AddressInfo).port;
});

afterAll(async () => {
  await new Promise<void>((resolve) => server.close(() => resolve()));
});

const savedEnv = { ...process.env };
beforeEach(() => {
  received = [];
  upstreamStatus = 200;
  process.env.NEXT_PUBLIC_SENTRY_DSN = `http://publickey@127.0.0.1:${port}/42`;
