7	 *
8	 * The body is handled as bytes from start to finish. Replay recordings are zlib-compressed binary
9	 * inside the envelope, and reading the body as text would replace every invalid UTF-8 sequence
10	 * with U+FFFD and corrupt them.
11	 *
12	 * Only the envelope header (the bytes up to the first `\n`) is parsed, to check that its DSN
13	 * names the configured host and project. Anything else gets 403 and is not forwarded, so the
14	 * route can't be used to relay traffic to an arbitrary host.
15	 *
16	 * Bodies over MAX_TUNNEL_BODY_BYTES get 413. The limit is enforced while reading, so a missing or
17	 * understated Content-Length can't make the route buffer more.
18	 */
19	
20	/** Well above a real envelope: the bug reporter keeps each replay segment under 1 MiB compressed. */
21	const MAX_TUNNEL_BODY_BYTES = 10 * 1024 * 1024;
22	
23	function tooLarge() {
24	  return new NextResponse("Payload Too Large", { status: 413 });
25	}
26	
27	/** The body's bytes, or null as soon as more than `limit` bytes have arrived. */
28	async function readBodyCapped(request: NextRequest, limit: number): Promise<Uint8Array | null> {
29	  if (!request.body) return new Uint8Array(0);
30	  const reader = request.body.getReader();
31	  const chunks: Uint8Array[] = [];
32	  let total = 0;
33	  for (;;) {
34	    const { done, value } = await reader.read();
35	    if (done) break;
36	    total += value.byteLength;
37	    if (total > limit) {
38	      await reader.cancel().catch(() => {});
39	      return null;
40	    }
41	    chunks.push(value);
42	  }
43	  const body = new Uint8Array(total);
44	  let offset = 0;
45	  for (const chunk of chunks) {
46	    body.set(chunk, offset);
47	    offset += chunk.byteLength;
48	  }
49	  return body;
50	}
